import { CONTRACTS, ETH_DIVISOR } from './chain-config.js';
import { ethers, getProvider } from './contracts.js';
import { permissionlessReadProvider, readProviderBlockNumber } from './read-provider.js';
import { deriveDeityBoonSlots } from './passes.js';
import { fetchJSON } from './api.js';

// Protocol boon draws (audit c5eaf15a onward). There is NO sacrifice transaction any more:
// Vault/sDGNRS.donateFlipForBoons and the Game's enterProtocolBoonDraw relay are gone. A draw
// entry is a side effect of an ordinary ETH Degenerette bet whose hero symbol is one of the two
// protocol deities' crypto symbols — symbol 0 (XRP) enters the Vault's draw, symbol 6 (ETH)
// enters sDGNRS's — weighted by the bet's 0.0001-ETH wager units times the bettor's activity
// multiplier (DegeneretteModule._enterProtocolBoonDraw). Gifted bets, FLIP bets and any
// boon boost carry no weight. So this module is READ-ONLY: pools, tomorrow's boons, and a
// quote of what a hero bet of a given size would weigh.
//
// Audit 224de529: pools and entries live in a two-day ring keyed by (day & 1), and the
// ProtocolBoonPool word carries its own `day`. GameLens.protocolBoonPool(game, issuer, day)
// resolves the ring and returns an all-zero pool when the slot belongs to another day.
export const SACRIFICE_DEITIES = Object.freeze([
  { key: 'vault', address: CONTRACTS.VAULT, name: 'WWXRP', keeper: 'The vault', heroSymbol: 0, heroName: 'XRP', symbol: '/badges-circular/crypto_00_xrp_red.svg' },
  { key: 'sdgnrs', address: CONTRACTS.SDGNRS, name: 'ETH', keeper: 'sDGNRS', heroSymbol: 6, heroName: 'ETH', symbol: '/badges-circular/crypto_06_ethereum_green.svg' },
]);
export const ETH_UNIT = 10n ** 18n;
// The hero ledger's wager unit and the lens quote floor are ETH literals the testnet overlay
// rescales (1e14 → 1e8, 0.005 ether → 5e9 wei), so derive both from the display divisor.
export const BOON_WAGER_UNIT_WEI = 10n ** 14n / BigInt(ETH_DIVISOR);
export const MIN_BOON_QUOTE_WEI = (5n * 10n ** 15n) / BigInt(ETH_DIVISOR);
const GAME_ABI = [
  'function currentDayView() view returns (uint24)',
  'function rngWordForDay(uint24 day) view returns (uint256)',
  'function gameOverTimestamp() view returns (uint48)',
  'function livenessTriggered() view returns (bool)',
];
const LENS_ABI = [
  'function protocolBoonPool(address game,address issuer,uint24 day) view returns (tuple(uint112 totalWageredWei,uint64 totalWeight,uint32 entryCount,uint8 awardedMask,uint24 day) pool)',
  'function protocolBoonQuote(address game,address player,uint256 amount) view returns (uint256 wagerUnits,uint16 score,uint16 multiplierUnits,uint64 weight)',
];
let contractFactory = (address, abi, runner) => new ethers.Contract(address, abi, runner);

/** Parse a display-ETH amount (what the player types) into raw chain wei. */
export function parseBoonWager(value) {
  const text = String(value ?? '').trim();
  if (!/^\d+(?:\.\d{1,18})?$/.test(text)) return null;
  try { return ethers.parseEther(text) / BigInt(ETH_DIVISOR); } catch { return null; }
}

/** The three protocol slots a funded pool always draws, with replacement. */
export const SACRIFICE_SLOTS_PER_POOL = 3;

/**
 * Read-only history for one wallet: its entries and the slots it has won.
 *
 * ⛔ CODE DEFENSIVELY. The route is served by the indexer, which publishes it
 * independently of this build, so a 404 means "no history surface yet" and NOT
 * "this wallet has never entered". Every failure degrades to an empty, explicitly
 * UNAVAILABLE result, and the altar keeps working on chain reads alone.
 *
 * Row shapes, as the route serves them (both halves are always ARRAYS, never null,
 * and the wide fields stay STRINGS because `amount` is a uint256 and `weight` a uint64):
 *   entries[] { issuer, player, day, amount, scoreSnapshot,
 *               weight, entryIndex, blockNumber, transactionHash, logIndex }
 *   awards[]  { issuer, player, day, slot, entryIndex, boonKind, boonType,
 *               blockNumber, transactionHash, logIndex }
 * A bettor who won nothing still appears in `entries` — that population is the whole
 * point of publishing the weighting, so never infer "no entry" from an empty `awards`.
 *
 * @returns {Promise<{available:boolean, entries:Array<object>, awards:Array<object>}>}
 */
export async function readSacrificeHistory(player, { limit = 25, signal, force = false } = {}) {
  const empty = Object.freeze({ available: false, entries: [], awards: [] });
  const wallet = String(player ?? '').trim();
  if (!ethers.isAddress(wallet)) return empty;
  // The route rejects a limit outside 1..500 with a 400 rather than scanning.
  const count = Math.max(1, Math.min(500, Math.trunc(Number(limit)) || 25));
  let payload = null;
  try {
    // ⛔ NO `/api` PREFIX. `fetchJSON` prepends CHAIN.indexerBase, and the indexer
    // registers the game routes under `/game` (server.ts), exactly like the
    // `/game/jackpot/last-day` payload this app already reads.
    payload = await fetchJSON(
      `/game/protocol-boon-draws?player=${wallet.toLowerCase()}&limit=${count}`,
      { signal, force },
    );
  } catch (_error) {
    // 404 (route not deployed), 5xx, offline, abort — all the same to the altar.
    return empty;
  }
  if (!payload || typeof payload !== 'object') return empty;
  const rows = (value) => (Array.isArray(value) ? value.filter((row) => row && typeof row === 'object') : []);
  return Object.freeze({
    available: true,
    entries: Object.freeze(rows(payload.entries)),
    awards: Object.freeze(rows(payload.awards)),
  });
}

/** Lowercase one address-ish value; '' when it is not one. */
function _addr(value) {
  const text = String(value ?? '').trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(text) ? text : '';
}

/**
 * Fold a wallet's OWN entries for one issuer and one pool day.
 *
 * A player may enter the same pool with many hero bets, and every entry keeps its own frozen
 * score snapshot, so the standing is the SUM of their weights — not a re-quote at today's
 * score. Returns zeroes (never null) so a panel can render before history loads.
 */
export function sacrificeStanding(entries, { issuer, day } = {}) {
  const wantIssuer = _addr(issuer);
  const wantDay = Number(day);
  let weight = 0n;
  let amountWei = 0n;
  let count = 0;
  for (const row of Array.isArray(entries) ? entries : []) {
    if (wantIssuer && _addr(row.issuer) !== wantIssuer) continue;
    if (Number.isInteger(wantDay) && Number(row.day) !== wantDay) continue;
    count += 1;
    try { weight += BigInt(row.weight ?? 0); } catch { /* malformed row */ }
    try { amountWei += BigInt(row.amount ?? 0); } catch { /* malformed row */ }
  }
  return Object.freeze({ count, weight, amountWei });
}

/**
 * Chance that a weight wins AT LEAST ONE of the pool's three slots.
 *
 * Each slot is an independent weighted draw WITH REPLACEMENT over the same pool, so
 * one player can take all three and the per-slot chances do not simply add.
 */
export function sacrificeAnySlotChance(weight, totalWeight) {
  let mine = 0n;
  let total = 0n;
  try { mine = BigInt(weight ?? 0); total = BigInt(totalWeight ?? 0); } catch { return null; }
  if (mine <= 0n || total <= 0n || mine > total) return mine > 0n && mine === total ? 1 : null;
  const perSlot = Number(mine) / Number(total);
  return 1 - ((1 - perSlot) ** SACRIFICE_SLOTS_PER_POOL);
}

/**
 * What an ETH hero bet of `amount` raw wei would weigh, and its chance after joining the pool.
 * Mirrors DegeneretteModule: weight = floor(amount / wager unit) × multiplierUnits (scale 800).
 * The lens quote refuses stakes under MIN_BOON_QUOTE_WEI; so does this.
 */
export function sacrificeQuote(amount, multiplierUnits, poolWeight) {
  if (amount == null || multiplierUnits == null || poolWeight == null) return null;
  const wei = BigInt(amount);
  const multiplier = BigInt(multiplierUnits);
  const total = BigInt(poolWeight);
  if (wei < MIN_BOON_QUOTE_WEI || multiplier < 800n || multiplier > 2400n || total < 0n) return null;
  const units = wei / BOON_WAGER_UNIT_WEI;
  const weight = units * multiplier;
  return {
    units, weight, multiplier: Number(multiplier) / 800,
    // This entry's chance of one slot, after adding it to the currently observed pool.
    chance: Number(weight) / Number(total + weight),
  };
}

/** Read one coherent block; tomorrow's menu uses TODAY's word and day + 1. */
export async function readSacrifices({ player = null } = {}) {
  const provider = permissionlessReadProvider(getProvider());
  if (!provider || !CONTRACTS.GAME_LENS || SACRIFICE_DEITIES.some((d) => !d.address)) return null;
  const game = contractFactory(CONTRACTS.GAME, GAME_ABI, provider);
  const lens = contractFactory(CONTRACTS.GAME_LENS, LENS_ABI, provider);
  const blockTag = await readProviderBlockNumber(provider);
  const opts = { blockTag };
  const [dayRaw, ended, timedOut, quote] = await Promise.all([
    game.currentDayView(opts), game.gameOverTimestamp(opts), game.livenessTriggered(opts),
    // The quote is only the wallet's activity multiplier at the smallest valid stake; weights
    // for any other size scale linearly (sacrificeQuote).
    player ? lens.protocolBoonQuote(CONTRACTS.GAME, player, MIN_BOON_QUOTE_WEI, opts).catch(() => null) : null,
  ]);
  const day = Number(dayRaw);
  if (!Number.isInteger(day) || day < 1 || day >= 0xffffff) return null;
  const [seed, pools] = await Promise.all([
    game.rngWordForDay(day, opts),
    Promise.all(SACRIFICE_DEITIES.map(async (deity) => {
      const pool = await lens.protocolBoonPool(CONTRACTS.GAME, deity.address, day, opts);
      return {
        key: deity.key,
        totalWageredWei: BigInt(pool.totalWageredWei ?? pool[0]),
        totalWeight: BigInt(pool.totalWeight ?? pool[1]),
        entryCount: Number(pool.entryCount ?? pool[2]),
        awardedMask: Number(pool.awardedMask ?? pool[3]),
        // Zero when the day's ring slot holds no pool for `day` (a stale slot reads as empty).
        day: Number(pool.day ?? pool[4] ?? 0),
      };
    })),
  ]);
  return {
    day, awardDay: day + 1, menuReady: BigInt(seed) !== 0n,
    ended: BigInt(ended) !== 0n || Boolean(timedOut),
    multiplierUnits: quote ? Number(quote.multiplierUnits ?? quote[2]) : null,
    score: quote ? Number(quote.score ?? quote[1]) : null,
    pools: pools.map((pool, index) => ({
      ...pool,
      slots: deriveDeityBoonSlots({ dailySeed: seed, deity: SACRIFICE_DEITIES[index].address, day: day + 1, includeCraps: true }),
    })),
  };
}

export function __setSacrificeContractFactoryForTest(factory) {
  contractFactory = factory || ((address, abi, runner) => new ethers.Contract(address, abi, runner));
}
